public class UrlBuilderTest {

    private static final String PROTOCOL = "https://example.com";
    private static final String PATH = "/path/to/resource";
    private static final String QUERY = "key=value&key2=value2";
    private static final String REF = "#anchor";
    private static final String SPACE = " ";
    private static final String NON_ASCII_CHAR = "\u00E0";

    @Test
    public void newUrlBuilder_withEmptyQuery_andREF_shouldReturnEmptyURL() {
        UrlBuilder builder = new UrlBuilder(new URL(PROTOCOL, PATH));
        assert builder.build().getProtocol().equals(PROTOCOL) && builder.build().getPath().isEmpty();
    }

    @Test
    public void newUrlBuilder_withNonASCII_PATH_shouldReturnNormalizedURL() {
        UrlBuilder builder = new UrlBuilder(new URL(PROTOCOL + "://example.com" + PATH));
        assert builder.build().getProtocol().equals(PROTOCOL) && builder.build().getPath().equals("path/to/resource");
    }

    @Test
    public void appendKeyVal_withNonASCII_KEY_shouldReturnNormalizedURL() {
        UrlBuilder builder = new UrlBuilder(new URL(PROTOCOL, PATH));
        builder.appendKeyVal(Connection.KeyVal.of("key", "non-ascii-key"));
        assert builder.build().getProtocol().equals(PROTOCOL) && builder.build().getPath().equals(PATH);
    }

    @Test
    public void appendToAscii_shouldEscapeNonASCII_CHAR() {
        StringBuilder sb = StringUtil.borrowBuilder();
        appendToAscii(NON_ASCII_CHAR, false, sb);
        assert sb.toString().equals("%C3%A0");
    }

    @Test
    public void appendKeyVal_withoutExistingQuery_shouldAppendNewOne() {
        UrlBuilder builder = new UrlBuilder(new URL(PROTOCOL, PATH));
        builder.appendKeyVal(Connection.KeyVal.of("key", "value"));
        assert builder.build().getProtocol().equals(PROTOCOL) && builder.build().getPath().equals(PATH);
    }

    @Test
    public void appendToAscii_shouldNotEscapeASCII_CHAR() {
        StringBuilder sb = StringUtil.borrowBuilder();
        appendToAscii(SPACE, false, sb);
        assert sb.toString().equals("+");
    }

    @Test
    public void build_withQuery_andREF_shouldReturnNormalizedURL() {
        UrlBuilder builder = new UrlBuilder(new URL(PROTOCOL + "://example.com" + PATH + "?" + QUERY));
        builder.appendKeyVal(Connection.KeyVal.of("key", REF));
        assert builder.build().getProtocol().equals(PROTOCOL) && builder.build().getPath().equals(PATH);
    }

    @Test
    public void build_shouldReturnOriginalURL_whenNormalizationFails() {
        UrlBuilder builder = new UrlBuilder(new URL(PROTOCOL + "://example.com" + PATH + "?" + QUERY));
        // Intentionally break normalization
        assert builder.build().equals(builder.u);
    }
}
